import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"周易尚氏學 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"周易尚氏學 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"classics/shangshi/038.md","filePath":"classics/shangshi/038.md"}'),s={name:"classics/shangshi/038.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><p>遁月卦闢未。陰長陽消。小人道長。君子道消。遁者退也。避也。當陰盛之時。勢須退避。否則其禍有不可勝言者矣。故曰遁亨。蓋以行止論。潔身退隱。否所謂儉德避難也。無所謂亨。而以禍福論。防微慮遠。不事王侯。高尚其事。優遊事外。亨莫亨於是矣。故傳日適而亨也。陽大陰小。小利貞者。謂宜貞定也。傳曰浸而長。謂陰方長。長則消陽。故利於靜。不利於動也。</p><p>彖曰。遁亨。通而亨也。剛當位而應。與時行也。小利貞。浸而長也。通之時義大矣哉。</p><p>五當位。二有應。故曰剛當位而應。然而不能不適者。時不可也。故曰與時行。遁太早則有過情之譏。如嚴光是也。太晚則不能適。沉溺於小人之中。而不能免。如劉歆是也。行而宜之之謂義。故夫子極嘆時義之大。</p><p>象曰。天下有山。遁。君子以遠小人。不惡而嚴。</p><p>凡卦皆合上下卦以立名。乾健艮止。皆無退義。然而遁者。以乾與艮先後天皆居西北也。西北者幽潛無用之地。太玄謂曰冥。冥者明之藏也。故曰遁。乾為君子。遠遁在外。故曰遠小人。五應二。故曰不惡。然以有阻隔故。絕難為與。故曰不惡而嚴。蓋外不與絕。內實遠之也。</p><p>初六。通尾。厲。勿用有攸往。</p><p>爻象初為尾。初往應四。則為同性之二所阻。危厲之道也。勿往則免矣。</p><h3 id="象曰。遁尾之厲。不往何災也。" tabindex="-1">象曰。遁尾之厲。不往何災也。 <a class="header-anchor" href="#象曰。遁尾之厲。不往何災也。" aria-label="Permalink to “象曰。遁尾之厲。不往何災也。”">​</a></h3><p>艮為止。在艮宜靜。勿用有攸往。則無災矣。</p><p>六二。執之用黃牛之革。莫之勝說。</p><p>艮為牛。無妄六三或繫之牛是也。二居中。故曰黃牛。易林既濟之艮雲。伺候牛羊。同人之無妄雲。負牛上山。皆以艮為牛。艮為皮革。執持也止也。艮手為執。言二得中正。宜貞定自持。如牛革之固。莫能勝我而說去也。仍小利貞之怡（右下日）也。說脫同。</p><h3 id="象曰。執用黃牛。固態也。" tabindex="-1">象曰。執用黃牛。固態也。 <a class="header-anchor" href="#象曰。執用黃牛。固態也。" aria-label="Permalink to “象曰。執用黃牛。固態也。”">​</a></h3><p>巽為志。牛革者至固之物。持志如是。貞定極矣。故曰固志。固則不動。不動則不消陽。</p><p>九三。系遁。有疾厲。畜臣妾。吉。</p><p>巽為繩。故曰系。艮止故曰秒遁。言繫戀而不即遁也。巽為疾。三無應。往遇敵。故有疾厲。然下有重陰。承順於三。畜臣妾則吉。艮為臣妾也。巽疾象。詳履卦象傳注。艮臣象亦本易林。易林決（無左）之坎雲。君臣擾憂。坎中爻艮震。震為君。艮為臣。故曰君臣擾憂。又兌之艮雲。臣圍其君。亦以艮為臣。蓋艮為憧為僕。故為妾。臣與僕古不分。故為臣。由是知蹇六二曰。王臣塞蹇。小過六二曰。遇其巨。易原以艮為臣也。</p><h3 id="象曰。系遭之厲。有疾憊也。畜臣妾吉。不可大事也。" tabindex="-1">象曰。系遭之厲。有疾憊也。畜臣妾吉。不可大事也。 <a class="header-anchor" href="#象曰。系遭之厲。有疾憊也。畜臣妾吉。不可大事也。" aria-label="Permalink to “象曰。系遭之厲。有疾憊也。畜臣妾吉。不可大事也。”">​</a></h3><p>廣韻。憊贏困也。陸績雲。大事謂天下之政。潛道之世。但可居家。畜養臣妾。不可治國之大事。</p><p>九四。好遁。君子吉。小人否。</p><p>虞翻曰。否乾為好為君子。陰稱小人。按四與初有應。好適者。外不與小人絕。當禍患未形之時。從容而遁也。然知幾其神。惟君子能之。若小人則繫戀而不去也。故曰君子吉。小人否。</p><h3 id="象曰。君子好遁。小人否也。" tabindex="-1">象曰。君子好遁。小人否也。 <a class="header-anchor" href="#象曰。君子好遁。小人否也。" aria-label="Permalink to “象曰。君子好遁。小人否也。”">​</a></h3><p>否不也。小人不肯退。不退則兇咎至矣。</p><p>九五。嘉遁。貞吉。</p><p>乾為嘉。五居中當位。下有應與。大必適也。乃識微慮遠。及此嘉時而遁焉。故曰貞吉。</p><h3 id="象曰。嘉遁貞吉。以王志也。" tabindex="-1">象曰。嘉遁貞吉。以王志也。 <a class="header-anchor" href="#象曰。嘉遁貞吉。以王志也。" aria-label="Permalink to “象曰。嘉遁貞吉。以王志也。”">​</a></h3><p>五應在二。二互巽。巽為伏。故為心志。虞翻用卦變謂四與初巳易位。三已變成坎。上來之三。成坎為志。夫聖人觀象繫辭。其所用象。乃在三變之後。迂曲如此。使後學鳥從測之哉。</p><p>上九。肥通。無不利。</p><p>子夏傳釋肥為饒裕。虞翻以乾盈為肥。皆非。後漢張衡傳。注引淮南九師訓雲。飛而能適。吉孰大焉。易林需之遁雲。去如飛鴻。節之道雲。奮翅鼓翼。王弼雲。曾（左矢）繳不能及。並皆讀為飛。朱芹引姚寬西溪叢語云。肥古作琶。琶蜚同字。是肥即蜚。蜚即飛也。蓋上九居極上。高飛遠引。無有阻隔。故無不利。而乾為行。故為飛。乾九五飛龍在天是也。</p><h3 id="象曰。肥遁無不利。無所疑也。" tabindex="-1">象曰。肥遁無不利。無所疑也。 <a class="header-anchor" href="#象曰。肥遁無不利。無所疑也。" aria-label="Permalink to “象曰。肥遁無不利。無所疑也。”">​</a></h3><p>上九逍遙世外。故無所疑。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
